     "4. A válvula fornece uma vedação metal-metal entre a esfera e o assento cunhado.",
     "5. A vedação da interface é de poliuretano que resiste à extrusão de alta pressão.",
     "6. Um retentor de válvula rosqueado fornece um batente de válvula que garante o alinhamento positivo da válvula.",
