 "lsq-o2-kr-estrutura-basica-de-engate-rapido-de-alta-pressao": {
  "breadcrumb": [],
  "sku": "LSQ-O2/KR",
  "blocks": [
   {
    "type": "p",
    "lines": [
     "Este modelo é caracterizado por estrutura simples, boa vedação e durabilidade. Ele pode suportar ambientes ruins, por exemplo, em poeira ou na areia, e é fácil de desinstalar e limpar. A chave do produto é fazer os acoplamentos para oxigênio e para acetileno em duas especificações, que não são intercambiáveis, de modo a dividir o caminho de dois tipos de gases e garantir a segurança. O design é tipicamente útil para fabricação de remessa, vedação de gás em serviços de reparo, etc."
    ]
   },
   {
    "type": "img",
    "src": "/products/lsq-o2-kr-estrutura-basica-de-engate-rapido-de-alta-pressao/desenho-01.webp",
    "w": 560,
    "h": 218
   }
  ]
 },
